import { MenuBar, type MenuBarSelectDetail } from '@absoluteui/components/menu-bar';

const host = document.createElement('div');
document.body.append(host);
MenuBar.create(host, {
  label: 'Editor',
  items: [
    { id: 'file', label: 'File', items: [
      { id: 'new', label: 'New', shortcut: 'Ctrl+N' },
      { id: 'open-recent', label: 'Open recent', items: [{ id: 'recent-report', label: 'report.md' }] },
      { type: 'separator' },
      { id: 'close-file', label: 'Close', tone: 'danger' },
    ] },
    { id: 'edit', label: 'Edit', items: [
      { id: 'undo', label: 'Undo', shortcut: 'Ctrl+Z' },
      { id: 'redo', label: 'Redo', shortcut: 'Ctrl+Y' },
    ] },
    { id: 'help', label: 'Help' },
  ],
});
// Command items and menu items both bubble aui-select to the host.
host.addEventListener('aui-select', (event) => {
  const { id } = (event as CustomEvent<MenuBarSelectDetail>).detail;
  host.dataset.lastCommand = id;
});

import { MenuBar, type MenuBarSelectDetail } from '@absoluteui/components/menu-bar';

const host = document.querySelector<HTMLElement>('#app-menu');
if (host) {
  const bar = MenuBar.create(host, {
    label: 'Application',
    closeOnSelect: false,
    items: [
      { id: 'view', label: 'View', items: [
        { type: 'checkbox', id: 'grid', label: 'Show grid', checked: true },
        { type: 'group', label: 'Zoom', items: [
          { type: 'radio', id: 'zoom-100', label: '100%', group: 'zoom', checked: true },
          { type: 'radio', id: 'zoom-200', label: '200%', group: 'zoom', checked: false },
        ] },
      ] },
      { id: 'tools', label: 'Tools', disabled: true, items: [{ id: 'macros', label: 'Macros' }] },
    ],
  });
  host.addEventListener('aui-select', (event) => {
    const { id, checked } = (event as CustomEvent<MenuBarSelectDetail>).detail;
    if (checked !== undefined) host.dataset[id] = String(checked);
  });
  bar.menu('view')?.element.addEventListener('aui-close', () => {
    host.dataset.viewMenu = 'closed';
  });
}
